document.querySelectorAll('[data-lab="L14-I1"]').forEach(root=>{if(root.dataset.ready)return;root.dataset.ready='1';const zh=root.dataset.lang==='zh',center=root.querySelector('[data-center]'),spring=root.querySelector('[data-spring]'),potential=root.querySelector('[data-potential]'),drawing=root.querySelector('[data-drawing]'),answer=root.querySelector('[data-feedback]'),RT=.00198720425864083*119.8;function update(){const c=Number(center.value),k=Number(spring.value),xx=Array.from({length:1281},(_,i)=>-32+i*.05),U=xx.map(x=>potential.value==='flat'?0:2.38*(Math.atan(x+10)-Math.atan(x-10))),logw=xx.map((x,i)=>-(U[i]+.5*k*(x-c)**2)/RT),top=Math.max(...logw),weight=logw.map(x=>Math.exp(x-top)),sum=weight.reduce((a,b)=>a+b,0),p=weight.map(w=>w/sum/.05),mean=xx.reduce((a,x,i)=>a+x*weight[i],0)/sum,sd=Math.sqrt(xx.reduce((a,x,i)=>a+(x-mean)**2*weight[i],0)/sum),pmax=Math.max(...p),mapx=x=>90+(x+32)*730/64;let out='';const line=(x1,y1,x2,y2,col='#163840',dash='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="2" ${dash}/>`;const txt=(x,y,t,size=21,anchor='middle')=>`<text x="${x}" y="${y}" font-size="${size}" text-anchor="${anchor}" fill="#163840">${t}</text>`;out+=line(90,265,820,265)+line(90,95,90,265)+line(90,535,820,535)+line(90,350,90,535);out+=txt(450,45,zh?'弹簧中心与预测平均位置':'Restraint centre and predicted mean',25);out+=txt(95,80,'U / kcal mol⁻¹',19,'start')+txt(95,325,'p / Å⁻¹',19,'start');out+=`<polyline points="${xx.map((x,i)=>`${mapx(x)},${265-U[i]*21}`).join(' ')}" fill="none" stroke="#c16b3d" stroke-width="3"/>`;out+=`<polyline points="${xx.map((x,i)=>`${mapx(x)},${535-p[i]/pmax*165}`).join(' ')}" fill="none" stroke="#167d84" stroke-width="3"/>`;out+=line(mapx(c),350,mapx(c),535,'#c16b3d','stroke-dasharray="6 5"')+line(mapx(mean),350,mapx(mean),535,'#466eaa');for(const x of[-30,-20,-10,0,10,20,30]){out+=txt(mapx(x),292,x,18)+txt(mapx(x),565,x,18);}out+=txt(450,607,'x / Å',22)+txt(640,326,zh?'虚线：中心；蓝线：均值':'Dashed: centre; blue: mean',18);out+=txt(81,542,'0',17,'end')+txt(81,377,pmax.toFixed(2),17,'end');drawing.innerHTML=out;root.querySelector('[data-center-value]').textContent=c.toFixed(1);root.querySelector('[data-spring-value]').textContent=k.toFixed(2);answer.textContent=zh?`c=${c.toFixed(2)} Å；平均位置=${mean.toFixed(4)} Å；位置标准差=${sd.toFixed(4)} Å；平坦原势宽度 √(RT/k)=${Math.sqrt(RT/k).toFixed(4)} Å。${potential.value==='flat'?'平坦原势给出以弹簧中心为轴的高斯形式；图内按有限区间归一化。':'外势斜坡可使平均位置偏离弹簧中心。'}`:`c=${c.toFixed(2)} Å; mean=${mean.toFixed(4)} Å; position SD=${sd.toFixed(4)} Å; flat-potential width √(RT/k)=${Math.sqrt(RT/k).toFixed(4)} Å. ${potential.value==='flat'?'A flat potential gives a Gaussian form centred on the spring; the displayed finite interval is normalized.':'The external slope can displace the mean from the spring centre.'}`;}center.addEventListener('input',update);spring.addEventListener('input',update);potential.addEventListener('change',update);root.querySelector('[data-reset]').addEventListener('click',()=>{center.value='-8';spring.value='.5';potential.value='barrier';update();});update();});